CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_migrations VALUES(1);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1), total INTEGER NOT NULL, locked INTEGER NOT NULL, daily INTEGER NOT NULL, per_task INTEGER NOT NULL, state TEXT NOT NULL, goal TEXT NOT NULL);
INSERT OR IGNORE INTO settings VALUES(1,100000,50000,1000,500,'paused','Hitta verkliga problem och jämför möjliga experiment.');
CREATE TABLE IF NOT EXISTS owner(id INTEGER PRIMARY KEY CHECK(id=1), salt TEXT NOT NULL, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, csrf TEXT NOT NULL, expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(ip TEXT PRIMARY KEY, attempts INTEGER NOT NULL, since REAL NOT NULL);
CREATE TABLE IF NOT EXISTS agents(id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY, title TEXT NOT NULL, state TEXT NOT NULL, kind TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_development ON projects(kind) WHERE kind='development' AND state='active';
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, action_id TEXT UNIQUE NOT NULL, project_id TEXT REFERENCES projects(id), agent_id TEXT NOT NULL REFERENCES agents(id), title TEXT NOT NULL, context TEXT NOT NULL, criteria TEXT NOT NULL, cap INTEGER NOT NULL CHECK(cap>=0), phase TEXT NOT NULL, status TEXT NOT NULL, parent_id TEXT REFERENCES tasks(id), created TEXT NOT NULL, result TEXT, error TEXT, lease_until REAL, attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), started TEXT NOT NULL, finished TEXT, state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS proposals(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), version INTEGER NOT NULL, payload TEXT NOT NULL, digest TEXT NOT NULL, status TEXT NOT NULL, expires TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', UNIQUE(task_id,version));
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY, proposal_id TEXT NOT NULL REFERENCES proposals(id), version INTEGER NOT NULL, digest TEXT NOT NULL, decision TEXT NOT NULL, actor TEXT NOT NULL CHECK(actor='owner'), created TEXT NOT NULL, UNIQUE(proposal_id,version));
CREATE TABLE IF NOT EXISTS reservations(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), amount INTEGER NOT NULL CHECK(amount>=0), day TEXT NOT NULL, status TEXT NOT NULL, metadata TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS costs(id TEXT PRIMARY KEY, task_id TEXT REFERENCES tasks(id), agent_id TEXT REFERENCES agents(id), amount INTEGER NOT NULL CHECK(amount>=0), day TEXT NOT NULL, kind TEXT NOT NULL, metadata TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ideas(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), data TEXT NOT NULL, stage TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), url TEXT NOT NULL, title TEXT NOT NULL, retrieved TEXT NOT NULL, origin TEXT NOT NULL, claim TEXT NOT NULL, kind TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS files(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), name TEXT NOT NULL, content TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT, created TEXT NOT NULL, kind TEXT NOT NULL, message TEXT NOT NULL, task_id TEXT);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT, role TEXT NOT NULL, content TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workers(id TEXT PRIMARY KEY, heartbeat REAL NOT NULL);

